import { tags } from "typia";

/**
 * Comprehensive aggregated performance analytics for all sellers on the
 * platform, with weighted composite scores and individual metric values
 * representing seller health across sales, customer satisfaction, inventory
 * efficiency, operational reliability, and platform-specific custom metrics.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IShoppingMallSellerPerformanceAnalytics = {
  /** Unique identifier for the seller whose performance is being analyzed. */
  seller_id: string & tags.Format<"uuid">;

  /**
   * Total sales revenue generated by the seller across all orders. Calculated
   * as sum of order item prices, excluding returns and cancellations.
   */
  total_sales: number & tags.Minimum<0>;

  /**
   * Total number of successfully completed orders handled by the seller.
   * Excludes cancelled, returned, or failed orders.
   */
  total_orders: number & tags.Type<"int32"> & tags.Minimum<0>;

  /**
   * Percentage of inventory sold compared to total inventory available.
   * Calculated as total sales volume divided by total inventory stocked,
   * indicating inventory efficiency.
   *
   * A high sell-through rate indicates strong product-market fit and
   * efficient inventory management. A low rate suggests overstocking or weak
   * demand for the seller's products.
   */
  sell_through_rate: number & tags.Minimum<0> & tags.Maximum<1>;

  /**
   * Average customer rating based on all product reviews received by the
   * seller. Ratings are on a 5-point scale from 1 (poor) to 5 (excellent).
   *
   * This metric reflects overall customer satisfaction with product quality,
   * accuracy of descriptions, and shipping experience. Ratings below 4.0 may
   * trigger performance review interventions.
   */
  average_rating: number & tags.Minimum<0> & tags.Maximum<5>;

  /**
   * Percentage of orders shipped within the target fulfillment window
   * (typically 48 hours). Calculated as orders shipped on-time divided by
   * total orders processed.
   *
   * A high fulfillment rate indicates reliable logistics and operational
   * efficiency. Consistently low rates may indicate inventory management
   * issues or processing delays.
   */
  order_fulfillment_rate: number & tags.Minimum<0> & tags.Maximum<1>;

  /**
   * Percentage of orders that result in customer returns. Calculated as
   * number of returned items divided by total items sold.
   *
   * A high return rate may indicate product quality issues, inaccurate
   * descriptions, or mismatched customer expectations. Sustained high return
   * rates may trigger seller warnings or restrictions.
   */
  return_rate: number & tags.Minimum<0> & tags.Maximum<1>;

  /**
   * Percentage of customers who have made repeat purchases from this seller.
   * Calculated as number of repeat customers divided by total unique
   * customers.
   *
   * This metric measures seller ability to build customer loyalty. High
   * retention rates indicate strong customer relationships, exceptional
   * service, and product quality that encourages repeat business.
   */
  customer_retention_rate: number & tags.Minimum<0> & tags.Maximum<1>;

  /**
   * Number of times inventory is sold and replaced over a specific period.
   * Calculated as cost of goods sold divided by average inventory value.
   *
   * A high turnover ratio indicates efficient inventory management and strong
   * sales velocity. A low ratio may suggest overstocking, stagnant inventory,
   * or weak demand.
   */
  inventory_turnover_ratio: number & tags.Minimum<0>;

  /**
   * Composite performance score derived from weighted aggregation of all
   * performance indicators. Scores are scaled 0-100 based on
   * platform-specific performance benchmarks and weighting factors.
   *
   * The score provides a single metric for quick assessment of seller health,
   * combining sales volume, customer satisfaction, operational efficiency,
   * and inventory management. Higher scores indicate superior overall
   * performance and are used to determine seller tier levels and platform
   * incentives.
   */
  performance_score: number & tags.Minimum<0> & tags.Maximum<100>;

  /**
   * Number of currently active product listings the seller has available for
   * sale. Only includes products that are currently in stock and marked as
   * active in the catalog.
   */
  active_listings: number & tags.Type<"int32"> & tags.Minimum<0>;

  /**
   * Total number of product reviews received for all items sold by the
   * seller. Each review corresponds to one product and one transaction.
   */
  review_count: number & tags.Type<"int32"> & tags.Minimum<0>;

  /**
   * Timestamp indicating when the performance analytics data was last
   * recalculated and updated in the system.
   *
   * This field ensures data freshness and allows consumers to understand how
   * current the metrics are, as analytics are computed on-demand rather than
   * stored persistently for every seller.
   */
  last_updated: string & tags.Format<"date-time">;
};
